  function rrPad2(v) {
    return String(Math.max(0, Math.trunc(Number(v || 0) || 0))).padStart(2, '0');
  }

  function rrMonthName(mes) {
    var nomes = ['Janeiro', 'Fevereiro', 'Marco', 'Abril', 'Maio', 'Junho', 'Julho', 'Agosto', 'Setembro', 'Outubro', 'Novembro', 'Dezembro'];
    return nomes[Math.max(0, Math.min(11, Number(mes || 1) - 1))] || 'Mes';
  }

  function rrDateAtLocal(v) {
    if (!v) return null;
    try {
      if (Object.prototype.toString.call(v) === '[object Date]') {
        if (!Number.isFinite(v.getTime())) return null;
        return new Date(v.getFullYear(), v.getMonth(), v.getDate());
      }
      var txt = String(v || '').trim();
      if (!txt) return null;
      if (/^\d{4}-\d{2}-\d{2}$/.test(txt)) {
        var parts = txt.split('-');
        return new Date(Number(parts[0] || 0), Number(parts[1] || 1) - 1, Number(parts[2] || 1));
      }
      var parsed = new Date(txt);
      if (!Number.isFinite(parsed.getTime())) return null;
      return new Date(parsed.getFullYear(), parsed.getMonth(), parsed.getDate());
    } catch (_) {
      return null;
    }
  }

  function rrDateText(v) {
    var d = rrDateAtLocal(v);
    if (!d) return '';
    return [d.getFullYear(), rrPad2(d.getMonth() + 1), rrPad2(d.getDate())].join('-');
  }

  function rrAddDays(v, days) {
    var d = rrDateAtLocal(v);
    if (!d) return null;
    return new Date(d.getFullYear(), d.getMonth(), d.getDate() + Math.trunc(Number(days || 0) || 0));
  }

  function rrStartOfWeek(v) {
    var d = rrDateAtLocal(v) || rrDateAtLocal(new Date());
    var diff = (d.getDay() + 6) % 7;
    return rrAddDays(d, -diff);
  }

  function rrWeekRangeLabel(v) {
    var inicio = rrStartOfWeek(v);
    var fim = rrAddDays(inicio, 6);
    return rrFmtDate(inicio) + ' a ' + rrFmtDate(fim);
  }

  function rrSergioDateFieldLabel(field) {
    return String(field || '').trim() === 'data_entrega' ? 'Data de entrega' : 'Data prevista';
  }

  function rrSergioResolveDate(item, field) {
    var modo = String(field || 'data_prevista').trim() === 'data_entrega' ? 'data_entrega' : 'data_prevista';
    var primary = String(item && item[modo] || '').trim();
    var fallbackField = modo === 'data_prevista' ? 'data_entrega' : 'data_prevista';
    var fallback = String(item && item[fallbackField] || '').trim();
    var raw = primary || fallback || '';
    var date = rrDateAtLocal(raw);
    return {
      date: date,
      iso: rrDateText(date),
      sourceField: primary ? modo : (fallback ? fallbackField : ''),
      raw: raw
    };
  }

  function rrSergioBuildWeekData(items, opts) {
    var cfg = opts || {};
    var baseField = String(cfg.date_field || 'data_prevista').trim() === 'data_entrega' ? 'data_entrega' : 'data_prevista';
    var weekStart = rrStartOfWeek(cfg.week_start || new Date());
    var groups = [];
    var inWeek = [];
    var semData = [];
    var outsideWeek = [];
    for (var i = 0; i < 7; i += 1) {
      var dayDate = rrAddDays(weekStart, i);
      groups.push({
        index: i,
        iso: rrDateText(dayDate),
        date: dayDate,
        label: String(dayDate.toLocaleDateString('pt-BR', { weekday: 'long' }) || '').replace(/^\w/, function(ch) { return ch.toUpperCase(); }),
        items: []
      });
    }
    (Array.isArray(items) ? items : []).forEach(function(item) {
      var info = rrSergioResolveDate(item, baseField);
      if (!info.date || !info.iso) {
        semData.push(item);
        return;
      }
      var diffDays = Math.round((info.date.getTime() - weekStart.getTime()) / 86400000);
      if (diffDays < 0 || diffDays > 6) {
        outsideWeek.push(item);
        return;
      }
      groups[diffDays].items.push(item);
      inWeek.push(item);
    });
    return {
      baseField: baseField,
      weekStart: weekStart,
      weekEnd: rrAddDays(weekStart, 6),
      groups: groups,
      inWeek: inWeek,
      semData: semData,
      outsideWeek: outsideWeek
    };
  }

  function rrRemoveModal() {
    var old = document.getElementById('rr-modal-backdrop');
    if (old) old.remove();
  }

  function rrOpenModal(opts) {
    rrRemoveModal();
    var cfg = opts || {};
    var overlay = document.createElement('div');
    overlay.id = 'rr-modal-backdrop';
    overlay.innerHTML = ''
      + '<div class="rr-modal">'
      + '  <div class="rr-modal-head">'
      + '    <div>'
      + '      <div class="rr-modal-title">' + rrEsc(cfg.title || 'Relatório') + '</div>'
      + '      <div class="rr-modal-sub">' + rrEsc(cfg.subtitle || '') + '</div>'
      + '    </div>'
      + '    <button type="button" class="rr-close" data-rr-close>Fechar</button>'
      + '  </div>'
      + '  <div id="rr-modal-body"></div>'
      + '</div>';
    overlay.addEventListener('click', function(ev) {
      if (ev.target === overlay) rrRemoveModal();
    });
    document.body.appendChild(overlay);
    Array.prototype.slice.call(overlay.querySelectorAll('[data-rr-close]')).forEach(function(btn) {
      btn.onclick = rrRemoveModal;
    });
    var body = overlay.querySelector('#rr-modal-body');
    if (typeof cfg.render === 'function') cfg.render(body, overlay);
    return overlay;
  }

  function rrMonthYearOptions() {
    var ref = rrMonthRef();
    var anos = [];
    for (var ano = ref.ano - 3; ano <= ref.ano + 2; ano += 1) anos.push(ano);
    return { mes: ref.mes, ano: ref.ano, anos: anos };
  }

  function rrEmpId() {
    try {
      return String(
        (window._usuarioLogado && (window._usuarioLogado.emp_id || window._usuarioLogado.empId)) ||
        (window.CURRENT_USER && (window.CURRENT_USER.emp_id || window.CURRENT_USER.empId)) ||
        ''
      ).trim();
    } catch (_) {
      return '';
    }
  }

  function rrEmpresaQueryParts() {
    var st = rrState();
    var val = String(st && st.empresa || 'todas').trim().toLowerCase() || 'todas';
    if (val === 'todas' || val === 'all' || val === '*' || val === '') {
      return ['todas_empresas=1'];
    }
    return ['emp_id=' + encodeURIComponent(val)];
  }

  function rrFetchClientesLite(term) {
    var txt = String(term || '').trim();
    if (!txt) return Promise.resolve([]);
    return rrFetchJson('/api/clientes?search=' + encodeURIComponent(txt) + '&limit=8&lite=1').then(function(json) {
      return rrList(json, ['data', 'clientes']).map(function(row) {
        return {
          id: String(row && row.id || '').trim(),
          nome: String(row && (row.nome || row.rs || row.razao_social) || '').trim(),
          cidade: String(row && row.cidade || '').trim(),
          uf: String(row && row.uf || '').trim()
        };
      });
    }).catch(function() { return []; });
  }

  async function rrReportOfsEmAberto(params) {
    var filtroEmpresa = String(params && params.empresa || 'atual').trim();
    var qs = [];
    if (filtroEmpresa === 'todas') qs.push('emp_id=all');
    var json = await rrFetchJson('/api/relatorios/ofs-em-aberto' + (qs.length ? ('?' + qs.join('&')) : ''));
    var resumo = json && json.resumo || {};
    var rows = rrList(json, ['rows', 'data']);
    return rrOpenPrint({
      title: 'Relatório de OFs em Aberto',
      periodo: filtroEmpresa === 'todas' ? 'Todas as empresas' : 'Empresa atual',
      cards: [
        { label: 'OFs em Aberto', value: rrFmtNum(resumo.total_ofs || rows.length, 0), sub: 'Status Em aberto no sistema' },
        { label: 'Quantidade Total', value: rrFmtNum(resumo.quantidade_total || 0, 0), sub: 'Soma das quantidades' },
        { label: 'Valor Total', value: rrFmtMoney(resumo.valor_total || 0), sub: 'Somatório das OFs visíveis' },
        { label: 'Empresas', value: rrFmtNum(resumo.total_empresas || 0, 0), sub: filtroEmpresa === 'todas' ? 'Empresas no relatório' : 'Filtro atual' }
      ],
      summaryTitle: 'Resumo',
      summaryHeaders: ['Indicador', 'Valor'],
      summaryRows: [
        [rrEsc('Filtro'), rrEsc(filtroEmpresa === 'todas' ? 'Todas as empresas' : 'Empresa atual')],
        [rrEsc('OFs em aberto'), rrEsc(rrFmtNum(resumo.total_ofs || rows.length, 0))],
        [rrEsc('Quantidade total'), rrEsc(rrFmtNum(resumo.quantidade_total || 0, 0))],
        [rrEsc('Valor total'), rrEsc(rrFmtMoney(resumo.valor_total || 0))]
      ],
      detailTitle: 'Detalhamento das OFs em aberto',
      detailHeaders: ['OF', 'Cliente', 'Produto', 'Quantidade', 'Entrega', 'Máquina', 'Vendedor', 'Empresa'],
      detailRows: rows.map(function(row) {
        return [
          rrEsc(String(row && row.numero || '—')),
          rrEsc(String(row && row.cliente || '—')),
          rrEsc(String(row && row.produto || '—')),
          rrEsc(rrFmtNum(row && row.quantidade || 0, 0)),
          rrEsc(rrFmtDate(row && row.data_entrega)),
          rrEsc(String(row && row.maquina || '—')),
          rrEsc(String(row && row.vendedor || '—')),
          rrEsc(String(row && row.empresa_nome || '—'))
        ];
      }),
      emptySummaryCols: 2,
      emptyDetailCols: 8
    });
  }

  function rrOpenOfsEmAbertoModal() {
    rrOpenModal({
      title: 'OFs em Aberto',
      subtitle: 'Gere o relatório para a empresa atual ou para todas as empresas cadastradas.',
      render: function(body) {
        body.innerHTML = ''
          + '<div class="rr-modal-grid">'
          + '  <div class="rr-modal-field full"><label>Escopo</label><select id="rr-ofs-abertas-empresa">'
          + '    <option value="atual">Empresa atual</option>'
          + '    <option value="todas">Todas as empresas</option>'
          + '  </select></div>'
          + '</div>'
          + '<div class="rr-modal-actions">'
          + '  <button type="button" class="rr-btn-ghost" data-rr-close>Cancelar</button>'
          + '  <button type="button" class="rr-btn" id="rr-ofs-abertas-gerar">Gerar relatório</button>'
          + '</div>';
        body.querySelector('#rr-ofs-abertas-gerar').onclick = async function() {
          var btn = this;
          btn.disabled = true;
          btn.textContent = 'Gerando...';
          try {
            await rrReportOfsEmAberto({ empresa: String((body.querySelector('#rr-ofs-abertas-empresa') || {}).value || 'atual') });
            rrRemoveModal();
          } catch (e) {
            alert('Erro ao gerar relatório: ' + String(e && e.message || e));
          } finally {
            btn.disabled = false;
            btn.textContent = 'Gerar relatório';
          }
        };
      }
    });
  }

  async function rrReportFichaCliente(clienteId) {
    var json = await rrFetchJson('/api/relatorios/cliente-ficha?cliente_id=' + encodeURIComponent(String(clienteId || '').trim()));
    var cliente = json && json.cliente || {};
    var resumo = json && json.resumo || {};
    var insights = json && json.insights || {};
    var produtos = rrList(json, ['produtos_mais_pedidos']);
    var historico = rrList(json, ['historico_ofs']);
    var orcamentos = rrList(json, ['orcamentos']);
    var faturamentoMensal = rrList(json, ['faturamento_mensal']);
    var ticketMedio = Number(resumo && resumo.total_ofs || 0) > 0 ? ((Number(resumo && resumo.total_comprado || 0) || 0) / Number(resumo.total_ofs || 1)) : 0;
    var topTxt = function(item, key) {
      var nome = String(item && item[key] || '').trim();
      if (!nome) return '—';
      var total = Number(item && item.total_ofs || 0) || 0;
      return total > 0 ? (nome + ' (' + rrFmtNum(total, 0) + ' OFs)') : nome;
    };
    var topListTxt = function(list, key) {
      return rrList({ value: list }, ['value']).map(function(item) {
        return topTxt(item, key);
      }).filter(function(txt) {
        return txt && txt !== '—';
      }).slice(0, 5).join(', ') || '—';
    };
    var freqTxt = resumo && resumo.frequencia_media_dias != null ? (rrFmtNum(resumo.frequencia_media_dias, 1) + ' dias') : '—';
    var mediaCaixasMesTxt = resumo && resumo.media_caixas_mes != null ? rrFmtNum(resumo.media_caixas_mes, 1) : '—';
    return rrOpenPrint({
      title: 'Ficha Técnica do Cliente',
      periodo: String(cliente && cliente.nome || 'Cliente'),
      cards: [
        { label: 'Total Comprado', value: rrFmtMoney(resumo.total_comprado || 0), sub: 'Somatório do histórico de OFs' },
        { label: 'Total de OFs', value: rrFmtNum(resumo.total_ofs || 0, 0), sub: 'Histórico localizado para o cliente' },
        { label: 'OFs em Aberto', value: rrFmtNum(resumo.ofs_abertas || 0, 0), sub: 'Pedidos ainda em produção/abertos' },
        { label: 'Orçamentos', value: rrFmtNum(resumo.total_orcamentos || 0, 0), sub: 'Orçamentos vinculados ao cliente' },
        { label: 'Frequência Média', value: freqTxt, sub: 'Intervalo médio entre pedidos do cliente' },
        { label: 'Média Caixas/Mês', value: mediaCaixasMesTxt, sub: 'Quantidade média de caixas pedidas por mês' }
      ],
      summaryTitle: 'Cadastro e indicadores',
      summaryHeaders: ['Campo', 'Valor'],
      summaryRows: [
        [rrEsc('Cliente'), rrEsc(String(cliente && cliente.nome || '—'))],
        [rrEsc('Razão social'), rrEsc(String(cliente && (cliente.razao_social || '—') || '—'))],
        [rrEsc('CNPJ'), rrEsc(String(cliente && (cliente.cnpj || '—') || '—'))],
        [rrEsc('Telefone'), rrEsc(String(cliente && (cliente.telefone || '—') || '—'))],
        [rrEsc('Email'), rrEsc(String(cliente && (cliente.email || '—') || '—'))],
        [rrEsc('Contato'), rrEsc(String(cliente && (cliente.contato || '—') || '—'))],
        [rrEsc('Cidade / UF'), rrEsc(((cliente && cliente.cidade) ? String(cliente.cidade) : '—') + ' / ' + ((cliente && cliente.uf) ? String(cliente.uf) : '—'))],
        [rrEsc('Ramo'), rrEsc(String(cliente && (cliente.ramo || '—') || '—'))],
        [rrEsc('Vendedor responsável'), rrEsc(String(cliente && (cliente.vendedor_nome || '—') || '—'))],
        [rrEsc('Valor total em orçamentos'), rrEsc(rrFmtMoney(resumo && resumo.valor_orcamentos || 0))],
        [rrEsc('Ticket médio'), rrEsc(rrFmtMoney(ticketMedio))],
        [rrEsc('Gramatura mais utilizada'), rrEsc(topTxt(insights && insights.gramatura_mais_utilizada, 'gramatura'))],
        [rrEsc('Tipo de caixa mais pedido'), rrEsc(topTxt(insights && insights.tipo_caixa_mais_pedido, 'tipo_caixa'))],
        [rrEsc('Frequência média entre pedidos'), rrEsc(freqTxt)],
        [rrEsc('Quantidade média de caixas por mês'), rrEsc(mediaCaixasMesTxt)],
        [rrEsc('Cores mais utilizadas'), rrEsc(topListTxt(insights && insights.cores_mais_utilizadas, 'cor'))],
        [rrEsc('Tamanhos mais utilizados'), rrEsc(topListTxt(insights && insights.tamanhos_mais_utilizados, 'tamanho'))]
      ],
      detailSections: [
        {
          title: 'Produtos Mais Pedidos',
          headers: ['Produto', 'OFs', 'Quantidade', 'Valor Total'],
          rows: produtos.map(function(row) {
            return [
              rrEsc(String(row && row.produto || '—')),
              rrEsc(rrFmtNum(row && row.total_ofs || 0, 0)),
              rrEsc(rrFmtNum(row && row.quantidade_total || 0, 0)),
              rrEsc(rrFmtMoney(row && row.valor_total || 0))
            ];
          }),
          emptyCols: 4
        },
        {
          title: 'Preferências do Cliente',
          headers: ['Indicador', 'Principal', 'Ranking complementar'],
          rows: [
            [rrEsc('Gramatura'), rrEsc(topTxt(insights && insights.gramatura_mais_utilizada, 'gramatura')), rrEsc(topListTxt(insights && insights.gramaturas_mais_utilizadas, 'gramatura'))],
            [rrEsc('Tipo de caixa'), rrEsc(topTxt(insights && insights.tipo_caixa_mais_pedido, 'tipo_caixa')), rrEsc(topListTxt(insights && insights.tipos_caixa_mais_pedidos, 'tipo_caixa'))],
            [rrEsc('Cores'), rrEsc(topListTxt(insights && insights.cores_mais_utilizadas, 'cor')), rrEsc('Frequência média: ' + freqTxt)],
            [rrEsc('Tamanhos'), rrEsc(topListTxt(insights && insights.tamanhos_mais_utilizados, 'tamanho')), rrEsc('Média de caixas/mês: ' + mediaCaixasMesTxt)]
          ],
          emptyCols: 3
        },
        {
          title: 'Orçamentos Vinculados',
          headers: ['Número', 'Orçamento', 'Medidas', 'Onda', 'Qtd', 'Valor Total', 'Status', 'Data'],
          rows: orcamentos.map(function(row) {
            return [
              rrEsc(String(row && row.numero || '—')),
              rrEsc(String(row && row.nome || '—')),
              rrEsc(String(row && row.medidas || '—')),
              rrEsc(String(row && row.onda || '—')),
              rrEsc(rrFmtNum(row && row.quantidade || 0, 0)),
              rrEsc(rrFmtMoney(row && row.valor_total || 0)),
              rrEsc(String(row && row.status || '—')),
              rrEsc(rrFmtDate(row && row.criado_em))
            ];
          }),
          emptyCols: 8
        },
        {
          title: 'Faturamento por Mês',
          headers: ['Mês/Ano', 'Qtd de OFs', 'Valor Total'],
          rows: faturamentoMensal.map(function(row) {
            var raw = String(row && row.mes_ano || '').trim();
            var meses = ['Jan','Fev','Mar','Abr','Mai','Jun','Jul','Ago','Set','Out','Nov','Dez'];
            var label = raw;
            try {
              var m = /^(\d{4})-(\d{2})$/.exec(raw);
              if (m) {
                var mesIdx = parseInt(m[2], 10) - 1;
                if (mesIdx >= 0 && mesIdx <= 11) label = meses[mesIdx] + ' / ' + m[1];
              }
            } catch (_) {}
            return [
              rrEsc(label),
              rrEsc(rrFmtNum(row && row.qtd_ofs || 0, 0)),
              rrEsc(rrFmtMoney(row && row.valor_total || 0))
            ];
          }),
          emptyCols: 3
        },
        {
          title: 'Histórico de OFs',
          headers: ['OF', 'Status', 'Produto', 'Qtd', 'Valor Total', 'Entrega', 'Conclusão', 'Máquina', 'Vendedor'],
          rows: historico.map(function(row) {
            return [
              rrEsc(String(row && row.numero || '—')),
              rrEsc(String(row && row.status || '—')),
              rrEsc(String(row && row.produto || '—')),
              rrEsc(rrFmtNum(row && row.quantidade || 0, 0)),
              rrEsc(rrFmtMoney(row && row.valor_total || 0)),
              rrEsc(rrFmtDate(row && row.data_entrega)),
              rrEsc(rrFmtDate(row && row.data_conclusao || row && row.data_entrada)),
              rrEsc(String(row && row.maquina || '—')),
              rrEsc(String(row && row.vendedor || '—'))
            ];
          }),
          emptyCols: 9
        }
      ],
      emptySummaryCols: 2,
      emptyDetailCols: 9
    });
  }

  function rrOpenFichaClienteModal() {
    rrOpenModal({
      title: 'Ficha Técnica do Cliente',
      subtitle: 'Busque o cliente e gere um relatório único com histórico, produtos, totais e orçamentos vinculados.',
      render: function(body) {
        body.innerHTML = ''
          + '<div class="rr-modal-grid">'
          + '  <div class="rr-modal-field full">'
          + '    <label>Cliente</label>'
          + '    <div class="rr-autocomplete" style="position:relative">'
          + '      <input type="text" id="rr-ficha-cli-nome" autocomplete="off" placeholder="Digite o nome do cliente">'
          + '      <input type="hidden" id="rr-ficha-cli-id">'
          + '      <div class="rr-suggest" id="rr-ficha-cli-suggest" style="display:none;position:absolute;top:calc(100% + 4px);left:0;right:0;z-index:4;max-height:220px;overflow:auto;background:#0f172a;border:1px solid rgba(148,163,184,.2);border-radius:12px;box-shadow:0 16px 36px rgba(2,6,23,.5)"></div>'
          + '    </div>'
          + '  </div>'
          + '</div>'
          + '<div class="rr-modal-actions">'
          + '  <button type="button" class="rr-btn-ghost" data-rr-close>Cancelar</button>'
          + '  <button type="button" class="rr-btn" id="rr-ficha-cli-gerar">Gerar relatório</button>'
          + '</div>';
        var input = body.querySelector('#rr-ficha-cli-nome');
        var hidden = body.querySelector('#rr-ficha-cli-id');
        var suggest = body.querySelector('#rr-ficha-cli-suggest');
        var lastResults = [];
        var paintSuggestions = function(rows) {
          lastResults = Array.isArray(rows) ? rows.slice() : [];
          if (!suggest) return;
          if (!lastResults.length) {
            suggest.style.display = 'none';
            suggest.innerHTML = '';
            return;
          }
          suggest.innerHTML = lastResults.map(function(row) {
            return '<button type="button" data-rr-cli-pick="' + rrEsc(String(row && row.id || '')) + '" style="width:100%;display:block;text-align:left;padding:10px 12px;border:none;background:transparent;color:#f8fafc;cursor:pointer">'
              + '<strong style="display:block">' + rrEsc(String(row && row.nome || 'Cliente')) + '</strong>'
              + '<span style="display:block;font-size:12px;color:#94a3b8">' + rrEsc([row && row.cidade, row && row.uf].filter(Boolean).join(' / ') || 'Sem localidade') + '</span>'
              + '</button>';
          }).join('');
          suggest.style.display = 'block';
          Array.prototype.slice.call(suggest.querySelectorAll('[data-rr-cli-pick]')).forEach(function(btn) {
            btn.onclick = function() {
              var id = String(btn.getAttribute('data-rr-cli-pick') || '').trim();
              var picked = lastResults.find(function(row) { return String(row && row.id || '').trim() === id; }) || null;
              if (!picked) return;
              if (input) input.value = String(picked.nome || '').trim();
              if (hidden) hidden.value = id;
              suggest.style.display = 'none';
              suggest.innerHTML = '';
            };
          });
        };
        if (input) {
          input.addEventListener('input', function() {
            var term = String(input.value || '').trim();
            if (hidden) hidden.value = '';
            if (term.length < 2) {
              paintSuggestions([]);
              return;
            }
            rrFetchClientesLite(term).then(paintSuggestions).catch(function() { paintSuggestions([]); });
          });
          input.addEventListener('focus', function() {
            var term = String(input.value || '').trim();
            if (term.length >= 2 && !lastResults.length) rrFetchClientesLite(term).then(paintSuggestions).catch(function() { paintSuggestions([]); });
          });
        }
        body.querySelector('#rr-ficha-cli-gerar').onclick = async function() {
          var btn = this;
          var clienteId = String((hidden || {}).value || '').trim();
          if (!clienteId && lastResults.length === 1) clienteId = String(lastResults[0] && lastResults[0].id || '').trim();
          if (!clienteId) {
            alert('Selecione um cliente na lista antes de gerar a ficha.');
            return;
          }
          btn.disabled = true;
          btn.textContent = 'Gerando...';
          try {
            await rrReportFichaCliente(clienteId);
            rrRemoveModal();
          } catch (e) {
            alert('Erro ao gerar relatório: ' + String(e && e.message || e));
          } finally {
            btn.disabled = false;
            btn.textContent = 'Gerar relatório';
          }
        };
      }
    });
  }

  async function rrReportOfsEntradasMes(params) {
    var now = new Date();
    var mes = Math.max(1, Math.min(12, Math.trunc(Number(params && params.mes || (now.getMonth() + 1)) || (now.getMonth() + 1))));
    var ano = Math.max(2000, Math.min(2100, Math.trunc(Number(params && params.ano || now.getFullYear()) || now.getFullYear())));
    var json = await rrFetchJson('/api/relatorios/ofs-entradas-mes?mes=' + encodeURIComponent(mes) + '&ano=' + encodeURIComponent(ano));
    var resumo = json && json.resumo || {};
    var rows = rrList(json, ['rows', 'data']);
    return rrOpenPrint({
      title: 'Relatório de Valor de OFs que Entraram no Mês',
      periodo: rrMonthName(mes) + ' / ' + String(ano),
      cards: [
        { label: 'OFs do Mês', value: rrFmtNum(resumo.total_ofs || rows.length, 0), sub: 'OFs criadas no período selecionado' },
        { label: 'Valor Total', value: rrFmtMoney(resumo.valor_total || rows.reduce(function(s, r) { return s + rrNum(r && r.valor_total); }, 0)), sub: 'Somatório do mês' },
        { label: 'Quantidade Total', value: rrFmtNum(resumo.quantidade_total || rows.reduce(function(s, r) { return s + rrInt(r && r.quantidade); }, 0), 0), sub: 'Itens produzidos/pedidos' },
        { label: 'Período', value: rrPad2(mes) + '/' + String(ano), sub: rrEsc(String(json && json.data_inicio || '') + ' a ' + String(json && json.data_fim || '')) }
      ],
      summaryTitle: 'Resumo mensal',
      summaryHeaders: ['Mês/Ano', 'OFs', 'Quantidade', 'Valor total'],
      summaryRows: [[rrEsc(rrPad2(mes) + '/' + String(ano)), rrEsc(rrFmtNum(resumo.total_ofs || rows.length, 0)), rrEsc(rrFmtNum(resumo.quantidade_total || 0, 0)), rrEsc(rrFmtMoney(resumo.valor_total || 0))]],
      detailTitle: 'OFs que entraram no mês',
      detailHeaders: ['Data de entrada', 'Nº da OF', 'Cliente', 'Produto', 'Quantidade', 'Valor unitário', 'Valor total'],
      detailRows: rows.map(function(row) {
        return [
          rrEsc(rrFmtDate(row && row.created_at)),
          rrEsc(String(row && row.numero || '—')),
          rrEsc(String(row && row.cliente_nome || '—')),
          rrEsc(String(row && row.produto || '—')),
          rrEsc(rrFmtNum(row && row.quantidade || 0, 0)),
          rrEsc(rrFmtMoney(row && row.valor_unitario || 0)),
          rrEsc(rrFmtMoney(row && row.valor_total || 0))
        ];
      }),
      emptySummaryCols: 4,
      emptyDetailCols: 7
    });
  }

