  function rrEnsureFreshPage(force) {
    rrEnsureCustosCard();
    var current = String(window._PAGE_ATUAL || '').trim();
    var host = document.getElementById('patch-page-body');
    var expected = rrDefsSignature();
    var rendered = String(host && host.getAttribute && host.getAttribute('data-rr-defs-sig') || '').trim();
    if (!force && current !== 'relatorios' && rendered === expected) return false;
    rrRenderPage();
    return true;
  }

  async function rrOpen(def) {
    if (!def || typeof def.run !== 'function') return;
    var btn = document.querySelector('[data-rr-open="' + String(def.id || '').replace(/"/g, '&quot;') + '"]');
    var old = btn ? btn.textContent : '';
    if (btn) {
      btn.disabled = true;
      btn.textContent = 'Gerando...';
    }
    try {
      rrLog('abrindo relatorio', def.id);
      await def.run();
    } catch (e) {
      rrLog('erro', def.id, e && e.message || e);
      try { alert('Erro ao abrir relatório: ' + String(e && e.message || e)); } catch (_) {}
    } finally {
      if (btn) {
        btn.disabled = false;
        btn.textContent = old || 'Abrir Relatório';
      }
    }
  }

  function rrPeriodHtml(ref) {
    var st = rrState();
    var personalizado = st.periodo === 'personalizado';
    var empSel = String(st.empresa || 'todas').trim() || 'todas';
    function empOpt(val, label, sel) {
      return '<option value="' + rrEsc(val) + '"' + (sel ? ' selected' : '') + '>' + rrEsc(label) + '</option>';
    }
    return ''
      + '<div class="rr-period">'
      + '  <div class="rr-period-grid">'
      + '    <div class="rr-field"><label>Período</label><select id="rr-periodo"><option value="dia"' + (st.periodo === 'dia' ? ' selected' : '') + '>Dia</option><option value="semana"' + (st.periodo === 'semana' ? ' selected' : '') + '>Semana</option><option value="mes"' + (st.periodo === 'mes' ? ' selected' : '') + '>Mês</option><option value="ano"' + (st.periodo === 'ano' ? ' selected' : '') + '>Ano</option><option value="personalizado"' + (personalizado ? ' selected' : '') + '>Personalizado</option></select></div>'
      + '    <div class="rr-field" id="rr-ref-wrap"' + (personalizado ? ' style="display:none"' : '') + '><label>Data de Referência</label><input id="rr-ref-date" type="date" value="' + rrEsc(st.data_referencia || ref.data_referencia || ref.data_inicio) + '"></div>'
      + '    <div class="rr-field" id="rr-inicio-wrap"' + (!personalizado ? ' style="display:none"' : '') + '><label>Data Início</label><input id="rr-data-inicio" type="date" value="' + rrEsc(st.data_inicio || ref.data_inicio) + '"></div>'
      + '    <div class="rr-field" id="rr-fim-wrap"' + (!personalizado ? ' style="display:none"' : '') + '><label>Data Fim</label><input id="rr-data-fim" type="date" value="' + rrEsc(st.data_fim || ref.data_fim) + '"></div>'
      + '    <div class="rr-field"><label>Empresa</label><select id="rr-empresa">'
      +        empOpt('todas', 'Todas as empresas', empSel === 'todas')
      +        empOpt('E1', 'Italy Embalagens (E1)', empSel === 'E1')
      +        empOpt('E2', 'Cartoeste (E2)', empSel === 'E2')
      +        empOpt('E3', 'Oestepack (E3)', empSel === 'E3')
      + '    </select></div>'
      + '    <div class="rr-field"><label>Aplicação</label><div class="rr-period-help">Período ativo: <strong>' + rrEsc(ref.titulo) + '</strong>. O filtro é usado em todos os relatórios da central.</div></div>'
      + '  </div>'
      + '</div>';
  }

  function rrBindPeriodControls(host) {
    if (!host) return;
    var st = rrState();
    var periodoEl = host.querySelector('#rr-periodo');
    var empresaEl = host.querySelector('#rr-empresa');
    var refEl = host.querySelector('#rr-ref-date');
    var iniEl = host.querySelector('#rr-data-inicio');
    var fimEl = host.querySelector('#rr-data-fim');
    function sync() {
      rrRenderPage();
    }
    if (empresaEl) empresaEl.onchange = function() {
      st.empresa = String(empresaEl.value || 'todas').trim() || 'todas';
      sync();
    };
    if (periodoEl) periodoEl.onchange = function() {
      st.periodo = String(periodoEl.value || 'mes').trim() || 'mes';
      if (st.periodo === 'personalizado') {
        st.auto_periodo_atual = false;
        st.data_inicio = rrClampDateText(st.data_inicio) || rrClampDateText(st.data_referencia) || rrTodayIso();
        st.data_fim = rrClampDateText(st.data_fim) || st.data_inicio;
      } else if (st.auto_periodo_atual !== false) {
        st.data_referencia = rrTodayIso();
      }
      sync();
    };
    if (refEl) refEl.onchange = function() {
      st.data_referencia = rrClampDateText(refEl.value) || st.data_referencia;
      st.auto_periodo_atual = st.data_referencia === rrTodayIso();
      sync();
    };
    if (iniEl) iniEl.onchange = function() {
      st.data_inicio = rrClampDateText(iniEl.value) || st.data_inicio;
      st.auto_periodo_atual = false;
      sync();
    };
    if (fimEl) fimEl.onchange = function() {
      st.data_fim = rrClampDateText(fimEl.value) || st.data_fim;
      st.auto_periodo_atual = false;
      sync();
    };
  }

  function rrRenderPage() {
    rrEnsureCustosCard();
    try { window.rrReportCustos = rrReportCustos; } catch (_) {}
    rrEnsureStyle();
    var host = rrHost();
    if (!host) return false;
    var ref = rrCurrentRange();
    var defsSig = rrDefsSignature();
    host.innerHTML = ''
      + '<div id="patch-relatorios-central">'
      + '  <div class="rr-panel">'
      + '    <div class="rr-head">'
      + '      <div>'
      + '        <div class="rr-title">Central de Relatórios</div>'
      + '        <div class="rr-sub">Área unificada com apenas relatórios existentes e funcionais, todos abrindo no mesmo padrão visual de impressão do sistema.</div>'
      + '      </div>'
      + '      <div class="rr-badge">Período ativo: ' + rrEsc(ref.titulo) + '</div>'
      + '    </div>'
      +       rrPeriodHtml(ref)
      + '    <div class="rr-search-row"><input id="rr-search-relatorios" class="rr-search-input" type="text" placeholder="Buscar relatório..." value="' + rrEsc(String(window.__rrBuscaRelatorios || '')) + '"></div>'
      + '  </div>'
      + '  <div class="rr-grid">'
      + rrDefs.map(function(def) {
          return ''
            + '<div class="rr-card" data-rr-search="' + rrEsc(((def.label || '') + ' ' + (def.desc || '')).toLowerCase()) + '">'
            + '  <div class="rr-card-top"><div class="rr-icon">' + rrEsc(def.icon || '🖨') + '</div></div>'
            + '  <div><div class="rr-label">' + rrEsc(def.label || 'Relatório') + '</div><div class="rr-desc">' + rrEsc(def.desc || '') + '</div></div>'
            + '  <button type="button" class="rr-btn" data-rr-open="' + rrEsc(def.id || '') + '">Abrir Relatório</button>'
            + '</div>';
        }).join('')
      + '  </div>'
      + '</div>';
    Array.prototype.slice.call(host.querySelectorAll('[data-rr-open]')).forEach(function(btn) {
      btn.onclick = function() {
        var id = String(btn.getAttribute('data-rr-open') || '').trim();
        var def = rrDefs.find(function(item) { return item.id === id; }) || null;
        rrOpen(def);
      };
    });
    (function() {
      var inp = host.querySelector('#rr-search-relatorios');
      if (!inp) return;
      var norm = function(v) { return String(v || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim(); };
      var apply = function() {
        var q = norm(inp.value || '');
        try { window.__rrBuscaRelatorios = inp.value || ''; } catch (_) {}
        Array.prototype.slice.call(host.querySelectorAll('.rr-card')).forEach(function(card) {
          var hay = norm(card.getAttribute('data-rr-search') || card.textContent || '');
          card.style.display = (!q || hay.indexOf(q) >= 0) ? '' : 'none';
        });
      };
      inp.addEventListener('input', apply);
      apply();
    })();
    try { host.setAttribute('data-rr-defs-sig', defsSig); } catch (_) {}
    rrBindPeriodControls(host);
    return true;
  }

  function rrInstallGoWrapper() {
    if (window.__rrGoWrapped) return;
    var origGo = window.go;
    if (typeof origGo !== 'function') return;
    function scheduleRelatoriosRefresh() {
      [0, 120, 400].forEach(function(ms) {
        setTimeout(function() {
          try {
            if (String(window._PAGE_ATUAL || '').trim() === 'relatorios') rrEnsureFreshPage(true);
          } catch (_) {}
        }, ms);
      });
    }
    window.go = function(id) {
      var pid = String(id || '').trim();
      var result = origGo.apply(this, arguments);
      if (pid === 'relatorios') {
        scheduleRelatoriosRefresh();
      }
      return result;
    };
    window.__rrGoWrapped = true;
  }

