    var selected = rows.find(function(row) { return sRowKey(row) === String(window.__simdSelectedRowId || '').trim(); }) || rows[0];
    var plan = window.__simdLastPlan || {};
    var sheetComp = Number(selected.chapa_comp_mm || 0) || 0;
