          ufs.sort(function(a,b){ return (a.uf||'').localeCompare(b.uf||''); }).forEach(function(e){
            opts.push('<option value="' + _p11Esc(e.uf||'') + '">' + _p11Esc(e.uf||'') + ' — ' + _p11Esc(e.nome||'') + '</option>');
          });
          sel.innerHTML = opts.join('');
