    if (titulo) titulo.textContent = String((row.nome || 'Chapa') + ' · ' + (row.tamanho || 'Sem tamanho'));
    svgHost.innerHTML = _simdBuildSvg(row);
    dadosHost.innerHTML = ''
      + '<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:10px">'
