      '#65A30D', '#CA8A04', '#EA580C', '#DC2626', '#DB2777',
      '#4F46E5', '#0284C7', '#0D9488', '#059669', '#9333EA',
      '#C2410C', '#B91C1C', '#BE185D', '#1D4ED8', '#4338CA'
