  function patchSalvarAntiDuploClique() {
    if (document.documentElement.dataset.patchClientesSalvarLock === '1') return;
    document.documentElement.dataset.patchClientesSalvarLock = '1';
    document.addEventListener('click', function(e) {
      try {
        var btn = e && e.target && e.target.closest ? e.target.closest('button') : null;
        if (!btn) return;
        var texto = String(btn.textContent || '').trim().toLowerCase();
        if (!(texto === 'salvar' || texto === 'salvar alteracoes' || texto === 'salvar alterações')) return;
        var modal = btn.closest ? btn.closest('.modal, [id*="modal"], .modal-overlay') : null;
        if (!clientesModalLike(modal)) return;
        if (btn.dataset.patchLockUntil && Number(btn.dataset.patchLockUntil) > Date.now()) {
          e.preventDefault();
          e.stopPropagation();
          return;
        }
        btn.disabled = true;
        btn.style.opacity = '0.6';
        btn.dataset.patchLockUntil = String(Date.now() + 2000);
        setTimeout(function() {
          try {
            btn.disabled = false;
            btn.style.opacity = '1';
            delete btn.dataset.patchLockUntil;
          } catch (_) {}
        }, 2000);
      } catch (_) {}
    }, true);
  }

  function patchFetchClientesAfterPost() {
    var origFetch = window.fetch;
    if (typeof origFetch !== 'function' || origFetch._patchClientesAfterPost) return;
    var wrapped = function(url, opts) {
      var isClientesPost = false;
      try {
        var u = typeof url === 'string' ? url : (url && url.url ? String(url.url) : '');
        var m = String((opts && opts.method) || 'GET').toUpperCase();
        isClientesPost = (m === 'POST' && u.indexOf('/api/clientes') !== -1);
      } catch (_) {}

      var p = origFetch.apply(this, arguments);

      if (isClientesPost) {
        try {
          p.then(function(res) {
            try { return res.clone().json(); } catch (_) { return null; }
          }).then(async function(data) {
            try {
              if (!(data && data.ok && data.data)) return;
              var novoCliente = data.data;
              console.log('[NOVO CLIENTE]', novoCliente.nome, novoCliente.id);
              try { salvarCatalogoRamosCliente(novoCliente && novoCliente.ramo); } catch (_) {}

              if (typeof carregarClientes === 'function') {
                try { await carregarClientes(true); } catch (_) { try { await carregarClientes(); } catch (_) {} }
              }

              var existe = null;
              try {
                var arr = (Array.isArray(window.CLIENTES) ? window.CLIENTES : ((typeof CLIENTES !== 'undefined' && Array.isArray(CLIENTES)) ? CLIENTES : []));
                existe = arr.find(function(c) { return String(c && c.id || '').trim() === String(novoCliente.id || '').trim(); }) || null;
              } catch (_) {}

              if (!existe) {
                console.log('[PATCH] adicionando cliente manualmente ao array');
                addClienteToArrays(novoCliente);
                try { await _carregarTodosClientes(); } catch (_) {}
              }

              if (typeof renderClientes === 'function') {
                try { renderClientes(); } catch (_) {}
              }
            } catch (_) {}
          }).catch(function() {});
        } catch (_) {}
      }

      return p;
    };
    wrapped._patchClientesAfterPost = true;
    window.fetch = wrapped;
  }

  function getCatalogoRamosCliente() {
    var lista = [];
    var vistos = Object.create(null);
    var add = function(valor) {
      var txt = String(valor || '').trim();
      if (!txt) return;
      var key = txt.toLocaleLowerCase('pt-BR');
      if (vistos[key]) return;
      vistos[key] = true;
      lista.push(txt);
    };

    ['Alimentício', 'Moveleiro', 'Calçados', 'Laticínios', 'Agronegócio', 'Comércio', 'Indústria', 'Serviços'].forEach(add);

    try {
      getClientesListaAtual().forEach(function(cliente) {
        add(cliente && cliente.ramo);
      });
    } catch (_) {}

    try {
      Array.prototype.forEach.call((document.getElementById('cli-ramo') || {}).options || [], function(opt) {
        add(opt && opt.value);
      });
    } catch (_) {}

    try {
      (Array.isArray(window.RAMOS) ? window.RAMOS : []).forEach(add);
    } catch (_) {}

    try {
      var raw = localStorage.getItem('ramos_atividade');
      var parsed = JSON.parse(raw || 'null');
      if (Array.isArray(parsed)) parsed.forEach(add);
    } catch (_) {}

    try { lista.sort(function(a, b) { return a.localeCompare(b, 'pt-BR', { sensitivity: 'base' }); }); } catch (_) {}
    return lista;
  }

  function salvarCatalogoRamosCliente(extraValor) {
    var lista = getCatalogoRamosCliente();
    var extra = String(extraValor || '').trim();
    if (extra && lista.indexOf(extra) === -1) {
      lista.push(extra);
      try { lista.sort(function(a, b) { return a.localeCompare(b, 'pt-BR', { sensitivity: 'base' }); }); } catch (_) {}
    }
    try { window.RAMOS = lista.slice(); } catch (_) {}
    try { localStorage.setItem('ramos_atividade', JSON.stringify(lista)); } catch (_) {}
    return lista;
  }

  function escapeRamoHtml(text) {
    return String(text == null ? '' : text)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#39;');
  }

  function renderNovoClienteRamoInput(valorAtual) {
    var lista = salvarCatalogoRamosCliente(valorAtual);
    var valAtual = String(valorAtual || '').trim();
    var opts = lista.map(function(item) {
      var safe = escapeRamoHtml(item);
      var sel = (valAtual && safe.toUpperCase() === valAtual.toUpperCase()) ? ' selected' : '';
      return '<option value="' + safe + '"' + sel + '>' + safe + '</option>';
    }).join('');
    return '<select id="novo-cli-ramo" style="width:100%;padding:10px 12px;background:var(--bg,#0b1220);border:1px solid var(--border,#273449);border-radius:8px;color:var(--text,#f8fafc)">' +
      '<option value="">— Selecione o ramo —</option>' +
      opts +
      '</select>';
  }

  function syncClienteRamoModalNativo() {
    try {
      var select = document.getElementById('cliente-ramo');
      if (!select) return;
      var atual = String(select.value || '').trim();
      var lista = salvarCatalogoRamosCliente(atual);
      var html = '<option value="">—</option>' + lista.map(function(item) {
        var safe = escapeRamoHtml(item);
        return '<option value="' + safe + '">' + safe + '</option>';
      }).join('');
      if (select.innerHTML !== html) select.innerHTML = html;
      if (atual) select.value = atual;
    } catch (_) {}
  }

